import{_ as a,a as t,a3 as i,o as s}from"./chunks/framework.yJBLK5ap.js";const u=JSON.parse('{"title":"Chainguard Builds","description":"","frontmatter":{},"headers":[],"relativePath":"dockerfiles/chainguard/README.md","filePath":"dockerfiles/chainguard/README.md","lastUpdated":1793987237000}'),d={name:"dockerfiles/chainguard/README.md"};function o(r,e,n,l,h,c){return s(),t("div",null,[...e[0]||(e[0]=[i(`<h1 id="chainguard-builds" tabindex="-1">Chainguard Builds <a class="header-anchor" href="#chainguard-builds" aria-label="Permalink to &quot;Chainguard Builds&quot;">​</a></h1><h2 id="tl-dr" tabindex="-1">TL;DR <a class="header-anchor" href="#tl-dr" aria-label="Permalink to &quot;TL;DR&quot;">​</a></h2><p>From the HPCC-Platform repository root:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">./dockerfiles/chainguard/build.sh</span></span></code></pre></div><p>This builds HPCC Platform and creates APK, DEB, RPM, and SBOM files using <strong>glibc 2.34 and GCC 11</strong>. Build files and packages go in:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>build/chainguard-hpcc-glibc2.34-gcc11-amd64/</span></span></code></pre></div><p>No LN checkout is required.</p><h2 id="setup" tabindex="-1">Setup <a class="header-anchor" href="#setup" aria-label="Permalink to &quot;Setup&quot;">​</a></h2><p>Use Docker or Podman with a running engine. macOS also supports Apple&#39;s <code>container</code> CLI; Windows supports Docker, Podman, or WSL containers (<code>wslc.exe</code>) from Git Bash.</p><p>For access to the default JFrog images and shared dependency cache, create <code>.env</code> in the HPCC-Platform repository root:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">JFROG_USERNAME</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">your.name@example.com</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">JFROG_PASSWORD</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;your-password-or-PAT&#39;</span></span></code></pre></div><p>Keep credentials out of version control. The file is optional if the required images are already available locally. Set <code>ENV_FILE</code> to use another file.</p><p>The build automatically pulls the builder image, reuses a local image if the pull fails, or builds one if needed. The first build can take longer while dependencies are downloaded and compiled.</p><p>APK builds require unprivileged user namespaces. The script checks this before building and reports any required host configuration.</p><h2 id="common-build-options" tabindex="-1">Common Build Options <a class="header-anchor" href="#common-build-options" aria-label="Permalink to &quot;Common Build Options&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Option</th><th>Purpose</th></tr></thead><tbody><tr><td><code>--glibc &lt;version&gt;</code></td><td>Change the glibc baseline; GCC follows the baseline unless overridden.</td></tr><tr><td><code>--gcc &lt;major&gt;</code></td><td>Override the GCC version.</td></tr><tr><td><code>--arch amd64</code> or <code>--arch arm64</code></td><td>Select the architecture; defaults to the host.</td></tr><tr><td><code>-f deb,rpm</code></td><td>Build only the listed formats instead of all three.</td></tr><tr><td><code>-b &lt;directory&gt;</code></td><td>Change the build directory.</td></tr><tr><td><code>-o &lt;directory&gt;</code></td><td>Write packages and SBOMs to a separate directory.</td></tr><tr><td><code>--containerized</code></td><td>Build for Kubernetes rather than host installation.</td></tr><tr><td><code>--no-pull</code></td><td>Reuse or build a local builder image without pulling it.</td></tr><tr><td><code>--help</code></td><td>Show all options.</td></tr></tbody></table><p>For example, build DEB and RPM packages with glibc 2.39 and its paired GCC 13:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">./dockerfiles/chainguard/build.sh</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --glibc</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 2.39</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -f</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> deb,rpm</span></span></code></pre></div><p>Each baseline and architecture gets a separate default build directory. Kubernetes builds also add <code>-containerized</code> to the directory name. If you use <code>-b</code>, keep separate directories for different toolchains and build modes.</p><p>The default glibc 2.34 baseline targets Ubuntu 21.10 or later, Rocky 9 or later, and Wolfi. Rocky 8 is not supported. Newer baselines require newer target libraries.</p><h2 id="run-cmake-directly" tabindex="-1">Run CMake Directly <a class="header-anchor" href="#run-cmake-directly" aria-label="Permalink to &quot;Run CMake Directly&quot;">​</a></h2><p>Use <a href="./cmake-chainguard.sh.html">cmake-chainguard.sh</a> to run a CMake command inside the builder with the same arguments:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">./dockerfiles/chainguard/cmake-chainguard.sh</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --version</span></span></code></pre></div><p>It defaults to glibc 2.34 and GCC 11. Set <code>CHAINGUARD_GLIBC</code> and <code>CHAINGUARD_GCC</code> to override them.</p><p>The proxy runs only the requested CMake command. It does not supply HPCC&#39;s configure flags, build automatically, or create packages. Use <a href="./build.sh.html">build.sh</a> for the complete HPCC build.</p><h2 id="build-a-development-image" tabindex="-1">Build a Development Image <a class="header-anchor" href="#build-a-development-image" aria-label="Permalink to &quot;Build a Development Image&quot;">​</a></h2><p>The build script handles this automatically. To prepare the default image separately:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">./dockerfiles/chainguard/create-build-image.sh</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --glibc</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 2.34</span></span></code></pre></div><p>Run <a href="./create-build-image.sh.html">create-build-image.sh</a> with <code>--help</code> for options.</p><h2 id="runtime-image-audit" tabindex="-1">Runtime Image Audit <a class="header-anchor" href="#runtime-image-audit" aria-label="Permalink to &quot;Runtime Image Audit&quot;">​</a></h2><p>The <code>runtime-audit</code> target in <a href="./containers/Dockerfile.runtime.html">Dockerfile.runtime</a> checks the assembled runtime before the final image can be built. Its Python check uses the native HPCC compiler, <code>eclcc -Me</code>, to evaluate a foldable <code>EMBED(Python3)</code> function inside the runtime rootfs. The function reads <code>sys.version_info</code>; its result must match <code>RUNTIME_PYTHON</code>, which must also match <code>PYTHON</code> in the packaged <code>hpcc-baseline</code>. Missing libraries, plugin initialization/evaluation failures, and version mismatches fail the audit rather than bypassing it.</p><p>Do not test <code>libpy3embed.so</code> with Python&#39;s <code>ctypes.CDLL</code>. This is an HPCC embedding plugin, not a Python extension: its global initialization initializes the interpreter and releases the GIL with <code>PyEval_SaveThread</code>. Loading it from an already-running Python interpreter interferes with that host&#39;s interpreter and thread state. The previous <code>ctypes</code> audit segfaulted (exit 139) with Python 3.12; that failure alone does not establish a packaging or ABI defect. Native ECL evaluation exercises the supported embedding path instead. This smoke check does not replace the Python embedding regression suite or prove that every distributed query works.</p><h2 id="ln-builds" tabindex="-1">LN Builds <a class="header-anchor" href="#ln-builds" aria-label="Permalink to &quot;LN Builds&quot;">​</a></h2><p>To build LN, run its wrapper from the LN repository root instead:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">./dockerfiles/chainguard/build.sh</span></span></code></pre></div><p>The wrapper uses the sibling HPCC-Platform checkout for tooling, reads LN&#39;s <code>.env</code>, and writes to <code>../build/chainguard-glibc2.34-gcc11/</code>. Use <code>-s /path/to/HPCC-Platform</code> to select another checkout.</p>`,36)])])}const g=a(d,[["render",o]]);export{u as __pageData,g as default};
